class Solution {
public:
    int minSessions(vector<int>& tasks, int sessionTime) {
        int n = tasks.size();
        vector<pair<int, int>> dp(1 << n, {n + 1, 0});
        dp[0] = {1, 0};
        for (int mask = 0; mask < (1 << n); mask++) {
            auto [sessions, cur_time] = dp[mask];
            for (int i = 0; i < n; i++) {
                if (!(mask & (1 << i))) {
                    int nxt_mask = mask | (1 << i);
                    pair<int, int> nxt_val;
                    if (cur_time + tasks[i] <= sessionTime) {
                        nxt_val = {sessions, cur_time + tasks[i]};
                    } else {
                        nxt_val = {sessions + 1, tasks[i]};
                    }
                    if (nxt_val < dp[nxt_mask]) {
                        dp[nxt_mask] = nxt_val;
                    }
                }
            }
        }
        return dp[(1 << n) - 1].first;
    }
};

import java.util.Arrays;

class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int[] sessions = new int[1 << n];
        int[] times = new int[1 << n];
        Arrays.fill(sessions, n + 1);
        sessions[0] = 1;
        times[0] = 0;

        for (int mask = 0; mask < (1 << n); mask++) {
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nxtMask = mask | (1 << i);
                    int nxtSess = sessions[mask];
                    int nxtTime = times[mask] + tasks[i];
                    if (nxtTime > sessionTime) {
                        nxtSess++;
                        nxtTime = tasks[i];
                    }
                    if (nxtSess < sessions[nxtMask] || (nxtSess == sessions[nxtMask] && nxtTime < times[nxtMask])) {
                        sessions[nxtMask] = nxtSess;
                        times[nxtMask] = nxtTime;
                    }
                }
            }
        }
        return sessions[(1 << n) - 1];
    }
}

